   604    const char *compname;
   605    int accel;
   606    int bscount;
   607    int doshuffle = (header_flags & BLOSC_DOSHUFFLE) && (typesize > 1);
   608    int dobitshuffle = ((header_flags & BLOSC_DOBITSHUFFLE) &&
   609                        (blocksize >= typesize));
