   612      /* Byte shuffling only makes sense if typesize > 1 */
   613      blosc_internal_shuffle(typesize, blocksize, src, tmp);
   614      _tmp = tmp;
   615    }
   616    /* We don't allow more than 1 filter at the same time (yet) */
