   318  static double get_cratio(uint8_t* ibase, int maxlen, int minlen, int ipshift) {
   319    uint8_t* ip = ibase;
   320    int32_t oc = 0;
   321    const uint16_t hashlen = (1U << (uint8_t)HASH_LOG2);
