   358      }
   359
   360      /* is this a match? check the first 4 bytes */
   540      else
   541        /* back, to overwrite the copy count */
   542        op--;
   543      /* reset literal counter */
   544      copy = 0;
   545
   546      /* encode the match */
   547      if (distance < MAX_DISTANCE) {
   548        if (len < 7) {
   549          MATCH_SHORT(op, op_limit, len, distance)
   550        } else {
   551          MATCH_LONG(op, op_limit, len, distance)
   552        }
   553      } else {
   554        /* far away, but not yet in the another galaxy... */
   555        distance -= MAX_DISTANCE;
   556        if (len < 7) {
   557          MATCH_SHORT_FAR(op, op_limit, len, distance)
   558        } else {
   559          MATCH_LONG_FAR(op, op_limit, len, distance)
